// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor, uint256 warpTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount != 10 ether); // admissible domain: all values except the exact required one
        warpTime = bound(warpTime, 1, type(uint256).max / 2); // any timestamp after genesis

        uint256 pastBefore = c.pastBlockTime(); // initially 0

        vm.warp(warpTime);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: a call not carrying exactly 10 ether never updates pastBlockTime.
        assertTrue(c.pastBlockTime() == pastBefore || (ok && amount == 10 ether));
    }
}
